import { useRef, useState } from 'react'

/**
 * Lights Out. Tapping a tile flips it and its four neighbours. Turn them all
 * off.
 *
 * The one game in the arcade you cannot win by being quick. Everything else
 * here rewards reflexes or recall, which leaves out the child who is simply
 * not fast — and that child is doing chores too. This one rewards sitting and
 * looking at it, and there is no clock anywhere in it.
 *
 * Every board is generated by starting from solved and making random legal
 * moves backwards, so it is always solvable. A random scramble is not: a bit
 * over half of all 5x5 arrangements have no solution at all, and handing a
 * nine-year-old an impossible puzzle is a quiet way of teaching them the app
 * cheats.
 */

const SIZE = 5
const SCRAMBLE = 6

const key = (r, c) => r * SIZE + c

function makeBoard() {
  const board = new Array(SIZE * SIZE).fill(false)
  const press = (r, c) => {
    for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const rr = r + dr
      const cc = c + dc
      if (rr >= 0 && rr < SIZE && cc >= 0 && cc < SIZE) board[key(rr, cc)] = !board[key(rr, cc)]
    }
  }
  // Backwards from solved, so a solution always exists — and the moves used
  // to scramble are themselves a solution, which is the par below.
  const used = new Set()
  while (used.size < SCRAMBLE) {
    const r = Math.floor(Math.random() * SIZE)
    const c = Math.floor(Math.random() * SIZE)
    if (used.has(key(r, c))) continue
    used.add(key(r, c))
    press(r, c)
  }
  // A board that scrambled back to solved would be no puzzle at all.
  if (board.every((on) => !on)) return makeBoard()
  return { board, par: used.size }
}

export default function LightsOut({ onDone }) {
  const start = useRef(makeBoard())
  const [board, setBoard] = useState(start.current.board)
  const [moves, setMoves] = useState(0)
  const done = useRef(false)

  const press = (r, c) => {
    if (done.current) return
    const next = [...board]
    for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const rr = r + dr
      const cc = c + dc
      if (rr >= 0 && rr < SIZE && cc >= 0 && cc < SIZE) next[key(rr, cc)] = !next[key(rr, cc)]
    }
    const count = moves + 1
    setBoard(next)
    setMoves(count)

    if (next.every((on) => !on)) {
      done.current = true
      /*
       * Solving it at all is most of the score. Par is the number of moves it
       * was scrambled with, so matching par is perfect and taking twice as
       * long still earns a good return — a child who got there the long way
       * round solved the same puzzle.
       */
      const par = start.current.par
      const efficiency = Math.min(1, par / Math.max(par, count))
      onDone(Math.round(70 + efficiency * 30))
    }
  }

  const give = () => {
    if (done.current) return
    done.current = true
    // Partial credit for how far they got, so quitting a hard board is not
    // punished to zero.
    const off = board.filter((on) => !on).length
    onDone(Math.round((off / board.length) * 45))
  }

  const lit = board.filter(Boolean).length

  return (
    <div className="text-center">
      <p className="text-sm text-muted mb-1">Turn them all off</p>
      <p className="font-display font-extrabold mb-3" style={{ fontSize: 22 }}>
        {lit} still on · {moves} {moves === 1 ? 'move' : 'moves'}
      </p>

      <div
        className="grid gap-2 mx-auto"
        style={{ maxWidth: 280, gridTemplateColumns: `repeat(${SIZE}, 1fr)` }}
      >
        {board.map((on, i) => {
          const r = Math.floor(i / SIZE)
          const c = i % SIZE
          return (
            <button
              // The grid is fixed and never reorders, so the index is the
              // tile's identity rather than a position in a changing list.
              // eslint-disable-next-line react/no-array-index-key
              key={i}
              type="button"
              aria-label={`Row ${r + 1} column ${c + 1}, ${on ? 'on' : 'off'}`}
              aria-pressed={on}
              onClick={() => press(r, c)}
              className="transition-transform active:scale-90"
              style={{
                aspectRatio: '1',
                borderRadius: 12,
                border: '2px solid rgb(255 255 255 / 0.1)',
                background: on
                  ? 'color-mix(in srgb, var(--accent) 78%, transparent)'
                  : 'color-mix(in srgb, var(--ink) 7%, transparent)',
                boxShadow: on ? '0 0 20px -6px var(--accent)' : 'none',
                transition: 'background 140ms ease, box-shadow 140ms ease',
              }}
            />
          )
        })}
      </div>

      <button type="button" onClick={give} className="btn btn-ghost mt-4">
        I'm stuck — take what I've got
      </button>
      <p className="text-xs text-muted mt-2">
        Tapping a tile flips it and the four around it. No timer.
      </p>
    </div>
  )
}
